// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListInstruments Tradable instruments
	// (GET /instruments)
	ListInstruments(ctx context.Context, request ListInstrumentsRequestObject) (ListInstrumentsResponseObject, error)
	// ListPendingActions Actions waiting for the caller's signature
	// (GET /tx/pending)
	ListPendingActions(ctx context.Context, request ListPendingActionsRequestObject) (ListPendingActionsResponseObject, error)
	// ExecuteAction Submit a pending action with the owner's signature over its hash
	// (POST /tx/{id}/execute)
	ExecuteAction(ctx context.Context, request ExecuteActionRequestObject) (ExecuteActionResponseObject, error)
	// GetBalances The caller's balances, every instrument included
	// (GET /wallet/balances)
	GetBalances(ctx context.Context, request GetBalancesRequestObject) (GetBalancesResponseObject, error)
	// Faucet Mint test tokens to the caller (local sandbox only)
	// (POST /wallet/faucet)
	Faucet(ctx context.Context, request FaucetRequestObject) (FaucetResponseObject, error)
	// ListIncoming Transfers to the caller waiting for acceptance
	// (GET /wallet/incoming)
	ListIncoming(ctx context.Context, request ListIncomingRequestObject) (ListIncomingResponseObject, error)
	// AcceptIncoming Accept an incoming transfer
	// (POST /wallet/incoming/{contractId}/accept)
	AcceptIncoming(ctx context.Context, request AcceptIncomingRequestObject) (AcceptIncomingResponseObject, error)
	// Withdraw Send holdings to any Canton party (it receives a transfer offer to accept)
	// (POST /wallet/withdraw)
	Withdraw(ctx context.Context, request WithdrawRequestObject) (WithdrawResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListInstruments operation middleware
func (sh *strictHandler) ListInstruments(w http.ResponseWriter, r *http.Request) {
	var request ListInstrumentsRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListInstruments(ctx, request.(ListInstrumentsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListInstruments")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListInstrumentsResponseObject); ok {
		if err := validResponse.VisitListInstrumentsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

